function pinyin($test)
{
    $text = hanzi();
    $pos = strpos($text, (string) $test);
    if ($pos === false) {
        return '';
    }
    $chunk = substr($text, $pos);
    $comma = strpos($chunk, ',');
    $r = $comma === false ? $chunk : substr($chunk, 0, $comma);
    return str_replace((string) $test, '', $r);
}
